    [Xunit.Fact]
    public static void TestAHealthyFontIsUntouchable() {
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells fl = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells ep = emon.Port.NewCells();
        emon.Port.Cells nfw = emon.Port.NewCells();
        emon.Port.Cells nfl = emon.Port.NewCells();
        emon.Port.Cells fv = emon.Port.NewCells();
        emon.Port.Cells fx = emon.Port.NewCells();
        emon.Port.Cells afa = emon.Port.NewCells();
        emon.Port.Cells gls = emon.Port.NewCells();
        int gz = AtGlyphs(gls);
        int w0 = AtTword(fw, feats, et, 0, 0, 0, 1000, 0, 104, 101);
        int w1 = AtTword(fw, feats, et, 1000, 0, 0, 1000, 0, 109, 111);
        int w2 = AtTword(fw, feats, et, 2000, 0, 0, 1000, 0, 120, 121);
        int o0 = AtOword(ow, feats, et, 0, 900, 0, 104, 101, 0);
        int o1 = AtOword(ow, feats, et, 1000, 1900, 0, 88, 89, 0);
        int o2 = AtOword(ow, feats, et, 2000, 2900, 0, 90, 90, 0);
        AtLine3(fl, 0, 3);
        // OCR agrees on the first, differs on the second, reads something else entirely (and plausibly) on the third
        AtGroup(cg, refs, w0, 1, o0, 1, 1000);
        AtGroup(cg, refs, w1, 1, o1, 1, 500);
        AtGroup(cg, refs, w2, 1, o2, 1, 0);
        emon.Testport.AssertEq(AtRun(cg, refs, fw, fl, et, feats, ow, im, ep, nfw, nfl, fv, fx, afa), 3, "three groups decided");
        emon.Testport.AssertEq(Player.FwCount(nfw), 3, "three words");
        emon.Testport.AssertEq(Player.FlCount(nfl), 1, "one line");
        int i = 0;
        while (i < 3) {
            emon.Testport.AssertEq(emon.Port.CellsAt(nfw, (i * 24) + 11), emon.Port.CellsAt(fw, (i * 24) + 11), "the text run is the text layer's");
            emon.Testport.AssertEq(emon.Port.CellsAt(nfw, (i * 24) + 12), 2, "its length");
            emon.Testport.AssertEq(emon.Port.CellsAt(nfw, (i * 24) + 17), 3, "its glyph run is kept");
            emon.Testport.AssertEq(emon.Port.CellsAt(nfw, (i * 24) + 1), emon.Port.CellsAt(fw, (i * 24) + 1), "its box is the text layer's");
            emon.Testport.AssertEq(emon.Port.CellsAt(nfw, (i * 24) + 23), 5, "src: text and ocr both had a candidate");
            emon.Testport.AssertEq(Player.FvGet(fv, i, 1), 1, "the verdict says `text`");
            i += 1;
        }
        emon.Testport.AssertEq(Player.FvGet(fv, 0, 2), 110, "agreement: rule 110");
        emon.Testport.AssertEq(Player.FvGet(fv, 0, 3), 1000, "at confidence 1000");
        emon.Testport.AssertEq(Player.FvGet(fv, 1, 2), 111, "disagreement: rule 111");
        emon.Testport.AssertEq(Player.FvGet(fv, 1, 3), 700, "at a lowered confidence");
        emon.Testport.AssertEq(Player.FvGet(fv, 2, 2), 112, "OCR reading something else entirely: rule 112, the text layer still wins");
        emon.Testport.AssertEq(Player.FvGet(fv, 2, 4), 1, "low-conf");
        emon.Testport.AssertEq(Player.FaCount(afa), 0, "nothing was set aside");
        emon.Testport.AssertThat(Player.FxCount(fx) > 8, "the explanation has the columns each rule read");
        emon.Testport.AssertEq(Player.PlCheck(cg, nfw, nfl, fv, emon.Port.NewCells(), fx, emon.Port.NewCells(), emon.Port.NewCells(), emon.Port.NewCells(), et, refs, gls), 0, "the layer is sound");
    }
