        emon.Testport.AssertEq(Player.FvGet(fv, 0, 2), 130, "rule 130");
        emon.Testport.AssertEq(Player.FvGet(fv, 0, 4), 4, "text-layer-suspect");
        emon.Testport.AssertEq(Player.FvGet(fv, 2, 1), 1, "the healthy font's word is the text layer's");
