        int w0 = AtTword(fw, feats, et, 0, 0, 0, 1000, 0, 104, 101);
        int o0 = AtOword(ow, feats, et, 0, 900, 0, 104, 101, 0);
        int o1 = AtOword(ow, feats, et, 5000, 5900, 900, 88, 89, 0);
        int o2 = AtOword(ow, feats, et, 6000, 6900, 0, 90, 91, 0);
        AtLine3(fl, 0, 1);
        Evidence.EpNew(ep, 1, 20000, 20000);
        // a small image holds the third OCR word's box (the area of the page is 400e6; the image 50e6: 125 per mille)
        Evidence.ImNew(im, 1, 5900, 0, 8000, 1000, 0, 10, 10);
        AtGroup(cg, refs, w0, 1, o0, 1, 1000);
        int g1 = AtOcrOnlyGroup(cg, refs, o1);
