        emon.Testport.AssertEq(g1, 1, "the second group");
        emon.Testport.AssertEq(g2, 2, "the third group");
        Player.CgSet(cg, g1, 1, 5000);
        Player.CgSet(cg, g1, 3, 5900);
        Player.CgSet(cg, g2, 1, 6000);
        Player.CgSet(cg, g2, 3, 7000);
        AtRun(cg, refs, fw, fl, et, feats, ow, im, ep, nfw, nfl, fv, fx, afa);
        emon.Testport.AssertEq(Player.FwCount(nfw), 1, "only the text layer's word is in the flow: the ghost and the figure's word are not");
